content.content:
   1→{% comment %}
   2→  Size Chart & Recommender — Size Chart App Block
   3→  Renders a trigger (button, link, or side-tab) on product pages.
   4→  Opens a fully-accessible popup or renders inline based on merchant config.
   5→  All JS is self-contained vanilla JS — no external dependencies.
   6→{% endcomment %}
   7→
   8→{% liquid
   9→  assign block_id   = block.id | replace: '-', '_'
  10→  assign shop_domain = shop.permanent_domain
  11→  assign product_id  = product.id | append: ''
  12→%}
  13→
  14→{%- comment -%} ── Inline mode container (hidden until chart loads) ──────── {%- endcomment -%}
  15→<div
  16→  id="scr-root-{{ block_id }}"
  17→  class="scr-root"
  18→  data-block-id="{{ block_id }}"
  19→  data-shop="{{ shop_domain }}"
  20→  data-product-id="{{ product_id }}"
  21→  data-display-mode="{{ block.settings.display_mode }}"
  22→  data-trigger-style="{{ block.settings.trigger_style }}"
  23→  data-button-text="{{ block.settings.button_text | escape }}"
  24→  data-primary-color="{{ block.settings.primary_color }}"
  25→  data-bg-color="{{ block.settings.background_color }}"
  26→  data-text-color="{{ block.settings.text_color }}"
  27→  data-border-radius="{{ block.settings.border_radius }}"
  28→>
  29→  {%- comment -%} Trigger element — JS populates this {%- endcomment -%}
  30→  <div id="scr-trigger-{{ block_id }}" class="scr-trigger-wrap" aria-live="polite"></div>
  31→
  32→  {%- comment -%} Inline chart container {%- endcomment -%}
  33→  <div
  34→    id="scr-inline-{{ block_id }}"
  35→    class="scr-inline-wrap"
  36→    aria-live="polite"
  37→    style="display:none;"
  38→  ></div>
  39→</div>
  40→
  41→{%- comment -%} ── Popup portal (appended to <body> by JS) ─────────────── {%- endcomment -%}
  42→<div
  43→  id="scr-modal-{{ block_id }}"
  44→  class="scr-modal"
  45→  role="dialog"
  46→  aria-modal="true"
  47→  aria-labelledby="scr-modal-title-{{ block_id }}"
  48→  tabindex="-1"
  49→  hidden
  50→>
  51→  <div class="scr-modal-backdrop" data-close="true"></div>
  52→  <div class="scr-modal-content" role="document">
  53→    {%- comment -%} Header {%- endcomment -%}
  54→    <div class="scr-modal-header">
  55→      <h2 id="scr-modal-title-{{ block_id }}" class="scr-modal-title">
  56→        {{ block.settings.button_text | escape }}
  57→      </h2>
  58→      <button
  59→        class="scr-modal-close"
  60→        type="button"
  61→        aria-label="{{ 'general.accessibility.close' | t | default: 'Close' }}"
  62→        data-close="true"
  63→      >
  64→        <svg width="20" height="20" viewBox="0 0 20 20" fill="none" aria-hidden="true" focusable="false">
  65→          <path d="M15 5L5 15M5 5l10 10" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
  66→        </svg>
  67→      </button>
  68→    </div>
  69→
  70→    {%- comment -%} Tab bar (hidden if recommender disabled) {%- endcomment -%}
  71→    <div class="scr-tabs" role="tablist" id="scr-tabs-{{ block_id }}">
  72→      <button
  73→        class="scr-tab scr-tab--active"
  74→        role="tab"
  75→        aria-selected="true"
  76→        aria-controls="scr-panel-chart-{{ block_id }}"
  77→        id="scr-tab-chart-{{ block_id }}"
  78→        data-tab="chart"
  79→        type="button"
  80→      >
  81→        {{ 'products.size_chart.tab_chart' | t | default: 'Size Chart' }}
  82→      </button>
  83→      <button
  84→        class="scr-tab"
  85→        role="tab"
  86→        aria-selected="false"
  87→        aria-controls="scr-panel-rec-{{ block_id }}"
  88→        id="scr-tab-rec-{{ block_id }}"
  89→        data-tab="recommender"
  90→        type="button"
  91→      >
  92→        {{ 'products.size_chart.tab_find' | t | default: 'Find My Size' }}
  93→      </button>
  94→    </div>
  95→
  96→    {%- comment -%} Chart panel {%- endcomment -%}
  97→    <div
  98→      id="scr-panel-chart-{{ block_id }}"
  99→      class="scr-panel scr-panel--active"
 100→      role="tabpanel"
 101→      aria-labelledby="scr-tab-chart-{{ block_id }}"
 102→    >
 103→      {%- comment -%} Unit toggle — shown only when both units available {%- endcomment -%}
 104→      <div class="scr-unit-toggle" id="scr-unit-toggle-{{ block_id }}" hidden>
 105→        <span class="scr-unit-label">{{ 'products.size_chart.units' | t | default: 'Units' }}:</span>
 106→        <div class="scr-unit-btn-group" role="group" aria-label="{{ 'products.size_chart.units' | t | default: 'Units' }}">
 107→          <button class="scr-unit-btn scr-unit-btn--active" data-unit="in" type="button">in</button>
 108→          <button class="scr-unit-btn" data-unit="cm" type="button">cm</button>
 109→        </div>
 110→      </div>
 111→
 112→      {%- comment -%} Loading state {%- endcomment -%}
 113→      <div class="scr-loading" id="scr-chart-loading-{{ block_id }}" aria-label="{{ 'products.size_chart.loading' | t | default: 'Loading size chart' }}">
 114→        <div class="scr-spinner" aria-hidden="true"></div>
 115→        <p class="scr-loading-text">{{ 'products.size_chart.loading' | t | default: 'Loading size chart…' }}</p>
 116→      </div>
 117→
 118→      {%- comment -%} Error state {%- endcomment -%}
 119→      <div class="scr-error" id="scr-chart-error-{{ block_id }}" hidden role="alert">
 120→        <p class="scr-error-text">{{ 'products.size_chart.error' | t | default: 'No size chart available for this product.' }}</p>
 121→      </div>
 122→
 123→      {%- comment -%} Table container {%- endcomment -%}
 124→      <div class="scr-table-wrap" id="scr-table-wrap-{{ block_id }}" hidden>
 125→        <div class="scr-table-scroll" tabindex="0" role="region" aria-label="{{ 'products.size_chart.table_label' | t | default: 'Size chart table, scroll horizontally for more columns' }}">
 126→          <table class="scr-table" id="scr-table-{{ block_id }}">
 127→            <thead class="scr-table-head" id="scr-table-head-{{ block_id }}"></thead>
 128→            <tbody class="scr-table-body" id="scr-table-body-{{ block_id }}"></tbody>
 129→          </table>
 130→        </div>
 131→        <p class="scr-scroll-hint" aria-hidden="true" id="scr-scroll-hint-{{ block_id }}">
 132→          {{ 'products.size_chart.scroll_hint' | t | default: 'Scroll right to see more' }} &rarr;
 133→        </p>
 134→      </div>
 135→    </div>
 136→
 137→    {%- comment -%} Recommender panel {%- endcomment -%}
 138→    <div
 139→      id="scr-panel-rec-{{ block_id }}"
 140→      class="scr-panel"
 141→      role="tabpanel"
 142→      aria-labelledby="scr-tab-rec-{{ block_id }}"
 143→      hidden
 144→    >
 145→      <form class="scr-rec-form" id="scr-rec-form-{{ block_id }}" novalidate>
 146→        <div class="scr-form-row">
 147→          {%- comment -%} Unit system {%- endcomment -%}
 148→          <fieldset class="scr-fieldset scr-fieldset--full">
 149→            <legend class="scr-legend">{{ 'products.size_chart.measurement_system' | t | default: 'Measurement System' }}</legend>
 150→            <div class="scr-radio-group">
 151→              <label class="scr-radio-label">
 152→                <input class="scr-radio" type="radio" name="unit" value="metric" checked>
 153→                <span>{{ 'products.size_chart.metric' | t | default: 'Metric (cm/kg)' }}</span>
 154→              </label>
 155→              <label class="scr-radio-label">
 156→                <input class="scr-radio" type="radio" name="unit" value="imperial">
 157→                <span>{{ 'products.size_chart.imperial' | t | default: 'Imperial (in/lbs)' }}</span>
 158→              </label>
 159→            </div>
 160→          </fieldset>
 161→        </div>
 162→
 163→        <div class="scr-form-row scr-form-row--two-col">
 164→          {%- comment -%} Height {%- endcomment -%}
 165→          <div class="scr-form-group">
 166→            <label class="scr-label" for="scr-height-{{ block_id }}">
 167→              {{ 'products.size_chart.height' | t | default: 'Height' }}
 168→              <span class="scr-unit-hint" id="scr-height-unit-{{ block_id }}">(cm)</span>
 169→            </label>
 170→            <input
 171→              class="scr-input"
 172→              type="number"
 173→              id="scr-height-{{ block_id }}"
 174→              name="height"
 175→              min="100"
 176→              max="250"
 177→              step="1"
 178→              placeholder="170"
 179→              required
 180→              aria-required="true"
 181→              aria-describedby="scr-height-err-{{ block_id }}"
 182→            >
 183→            <span class="scr-field-error" id="scr-height-err-{{ block_id }}" role="alert" hidden></span>
 184→          </div>
 185→
 186→          {%- comment -%} Weight {%- endcomment -%}
 187→          <div class="scr-form-group">
 188→            <label class="scr-label" for="scr-weight-{{ block_id }}">
 189→              {{ 'products.size_chart.weight' | t | default: 'Weight' }}
 190→              <span class="scr-unit-hint" id="scr-weight-unit-{{ block_id }}">(kg)</span>
 191→            </label>
 192→            <input
 193→              class="scr-input"
 194→              type="number"
 195→              id="scr-weight-{{ block_id }}"
 196→              name="weight"
 197→              min="30"
 198→              max="300"
 199→              step="0.5"
 200→              placeholder="65"
 201→              required
 202→              aria-required="true"
 203→              aria-describedby="scr-weight-err-{{ block_id }}"
 204→            >
 205→            <span class="scr-field-error" id="scr-weight-err-{{ block_id }}" role="alert" hidden></span>
 206→          </div>
 207→        </div>
 208→
 209→        <div class="scr-form-row scr-form-row--two-col">
 210→          {%- comment -%} Gender {%- endcomment -%}
 211→          <div class="scr-form-group">
 212→            <label class="scr-label" for="scr-gender-{{ block_id }}">
 213→              {{ 'products.size_chart.gender' | t | default: 'Gender' }}
 214→            </label>
 215→            <select class="scr-select" id="scr-gender-{{ block_id }}" name="gender" required aria-required="true">
 216→              <option value="female">{{ 'products.size_chart.gender_female' | t | default: 'Female' }}</option>
 217→              <option value="male">{{ 'products.size_chart.gender_male' | t | default: 'Male' }}</option>
 218→              <option value="unisex">{{ 'products.size_chart.gender_unisex' | t | default: 'Unisex / Other' }}</option>
 219→            </select>
 220→          </div>
 221→
 222→          {%- comment -%} Body type {%- endcomment -%}
 223→          <div class="scr-form-group">
 224→            <label class="scr-label" for="scr-bodytype-{{ block_id }}">
 225→              {{ 'products.size_chart.body_type' | t | default: 'Body Type' }}
 226→            </label>
 227→            <select class="scr-select" id="scr-bodytype-{{ block_id }}" name="bodyType" required aria-required="true">
 228→              <option value="slim">{{ 'products.size_chart.body_slim' | t | default: 'Slim / Petite' }}</option>
 229→              <option value="average" selected>{{ 'products.size_chart.body_average' | t | default: 'Average' }}</option>
 230→              <option value="athletic">{{ 'products.size_chart.body_athletic' | t | default: 'Athletic / Muscular' }}</option>
 231→              <option value="plus">{{ 'products.size_chart.body_plus' | t | default: 'Plus / Curvy' }}</option>
 232→            </select>
 233→          </div>
 234→        </div>
 235→
 236→        {%- comment -%} Submit {%- endcomment -%}
 237→        <div class="scr-form-row">
 238→          <button class="scr-submit-btn" type="submit" id="scr-rec-submit-{{ block_id }}">
 239→            <span class="scr-submit-text">{{ 'products.size_chart.find_my_size' | t | default: 'Find My Size' }}</span>
 240→            <span class="scr-submit-spinner" aria-hidden="true" hidden></span>
 241→          </button>
 242→        </div>
 243→
 244→        {%- comment -%} Form-level error {%- endcomment -%}
 245→        <div class="scr-form-error" id="scr-rec-form-error-{{ block_id }}" role="alert" hidden></div>
 246→      </form>
 247→
 248→      {%- comment -%} Recommendation result {%- endcomment -%}
 249→      <div
 250→        class="scr-result"
 251→        id="scr-rec-result-{{ block_id }}"
 252→        aria-live="polite"
 253→        hidden
 254→      >
 255→        <div class="scr-result-badge">
 256→          <span class="scr-result-label">{{ 'products.size_chart.your_size' | t | default: 'Your Size' }}</span>
 257→          <span class="scr-result-size" id="scr-result-size-{{ block_id }}">—</span>
 258→        </div>
 259→        <p class="scr-result-message" id="scr-result-msg-{{ block_id }}"></p>
 260→        <div class="scr-result-alts" id="scr-result-alts-{{ block_id }}" hidden>
 261→          <p class="scr-alts-label">{{ 'products.size_chart.alternatives' | t | default: 'You might also consider:' }}</p>
 262→          <div class="scr-alts-list" id="scr-alts-list-{{ block_id }}"></div>
 263→        </div>
 264→        <button class="scr-redo-btn" type="button" id="scr-redo-btn-{{ block_id }}">
 265→          {{ 'products.size_chart.recalculate' | t | default: 'Recalculate' }}
 266→        </button>
 267→      </div>
 268→    </div>
 269→
 270→    {%- comment -%} Footer {%- endcomment -%}
 271→    <div class="scr-modal-footer">
 272→      <span class="scr-powered-by">
 273→        {{ 'products.size_chart.powered_by' | t | default: 'Powered by' }}
 274→        <a
 275→          href="https://apps.shopify.com/size-chart-recommender"
 276→          class="scr-powered-link"
 277→          target="_blank"
 278→          rel="noopener noreferrer"
 279→          aria-label="Size Chart &amp; Recommender app"
 280→        >Size Chart &amp; Recommender</a>
 281→      </span>
 282→    </div>
 283→  </div>
 284→</div>
 285→
 286→{%- comment -%} ══════════════════════════════════════════════════════════
 287→  STYLES — scoped with .scr- prefix, no global pollution
 288→══════════════════════════════════════════════════════════ {%- endcomment -%}
 289→<style>
 290→  /* ── Custom properties — overridden per-block via JS ── */
 291→  #scr-root-{{ block_id }} {
 292→    --scr-primary:    {{ block.settings.primary_color }};
 293→    --scr-bg:         {{ block.settings.background_color }};
 294→    --scr-text:       {{ block.settings.text_color }};
 295→    --scr-radius:     {{ block.settings.border_radius }}px;
 296→    --scr-success:    #16a34a;
 297→    --scr-error:      #dc2626;
 298→    --scr-border:     #e5e7eb;
 299→    --scr-muted:      #6b7280;
 300→    --scr-input-bg:   #f9fafb;
 301→    --scr-shadow:     0 20px 60px rgba(0,0,0,.18), 0 4px 16px rgba(0,0,0,.10);
 302→    --scr-anim:       250ms cubic-bezier(.4,0,.2,1);
 303→  }
 304→
 305→  /* ── Trigger ── */
 306→  .scr-trigger-wrap { display: inline-block; }
 307→
 308→  .scr-btn {
 309→    display: inline-flex;
 310→    align-items: center;
 311→    gap: .4em;
 312→    padding: .65em 1.4em;
 313→    background: var(--scr-primary);
 314→    color: #fff;
 315→    border: 2px solid var(--scr-primary);
 316→    border-radius: var(--scr-radius);
 317→    font-size: 1em;
 318→    font-weight: 600;
 319→    line-height: 1.2;
 320→    cursor: pointer;
 321→    text-decoration: none;
 322→    min-height: 44px;
 323→    min-width: 44px;
 324→    transition: opacity var(--scr-anim), transform var(--scr-anim);
 325→    -webkit-font-smoothing: antialiased;
 326→  }
 327→  .scr-btn:hover { opacity: .87; }
 328→  .scr-btn:active { transform: scale(.97); }
 329→  .scr-btn:focus-visible {
 330→    outline: 3px solid var(--scr-primary);
 331→    outline-offset: 3px;
 332→  }
 333→
 334→  .scr-link-trigger {
 335→    display: inline-flex;
 336→    align-items: center;
 337→    gap: .3em;
 338→    color: var(--scr-primary);
 339→    font-size: .95em;
 340→    font-weight: 500;
 341→    cursor: pointer;
 342→    text-decoration: underline;
 343→    background: none;
 344→    border: none;
 345→    padding: .4em 0;
 346→    min-height: 44px;
 347→    min-width: 44px;
 348→  }
 349→  .scr-link-trigger:focus-visible {
 350→    outline: 3px solid var(--scr-primary);
 351→    outline-offset: 2px;
 352→    border-radius: 2px;
 353→  }
 354→
 355→  /* Side-tab trigger */
 356→  .scr-tab-trigger {
 357→    position: fixed;
 358→    top: 50%;
 359→    right: 0;
 360→    transform: translateY(-50%) rotate(90deg);
 361→    transform-origin: right center;
 362→    background: var(--scr-primary);
 363→    color: #fff;
 364→    border: none;
 365→    border-radius: var(--scr-radius) var(--scr-radius) 0 0;
 366→    padding: .55em 1.1em;
 367→    font-size: .9em;
 368→    font-weight: 600;
 369→    cursor: pointer;
 370→    z-index: 9990;
 371→    white-space: nowrap;
 372→    min-height: 44px;
 373→    min-width: 44px;
 374→    writing-mode: horizontal-tb;
 375→  }
 376→  .scr-tab-trigger:focus-visible {
 377→    outline: 3px solid #fff;
 378→    outline-offset: 2px;
 379→  }
 380→
 381→  /* ── Inline container ── */
 382→  .scr-inline-wrap {
 383→    margin: 1rem 0;
 384→    border: 1px solid var(--scr-border);
 385→    border-radius: var(--scr-radius);
 386→    padding: 1rem;
 387→    background: var(--scr-bg);
 388→    color: var(--scr-text);
 389→  }
 390→
 391→  /* ── Backdrop ── */
 392→  .scr-modal {
 393→    position: fixed;
 394→    inset: 0;
 395→    z-index: 99999;
 396→    display: flex;
 397→    align-items: flex-end;
 398→    justify-content: center;
 399→  }
 400→  @media (min-width: 640px) {
 401→    .scr-modal { align-items: center; }
 402→  }
 403→  .scr-modal[hidden] { display: none; }
 404→
 405→  .scr-modal-backdrop {
 406→    position: absolute;
 407→    inset: 0;
 408→    background: rgba(0,0,0,.5);
 409→    -webkit-backdrop-filter: blur(2px);
 410→    backdrop-filter: blur(2px);
 411→    cursor: pointer;
 412→  }
 413→
 414→  /* ── Modal content ── */
 415→  .scr-modal-content {
 416→    position: relative;
 417→    z-index: 1;
 418→    background: var(--scr-bg, #fff);
 419→    color: var(--scr-text, #111);
 420→    border-radius: var(--scr-radius, 8px) var(--scr-radius, 8px) 0 0;
 421→    box-shadow: var(--scr-shadow);
 422→    width: 100%;
 423→    max-width: 560px;
 424→    max-height: 92dvh;
 425→    max-height: 92vh;
 426→    display: flex;
 427→    flex-direction: column;
 428→    overflow: hidden;
 429→    animation: scrSlideUp var(--scr-anim) both;
 430→  }
 431→  @media (min-width: 640px) {
 432→    .scr-modal-content {
 433→      border-radius: var(--scr-radius, 8px);
 434→      max-height: 88vh;
 435→    }
 436→  }
 437→
 438→  @keyframes scrSlideUp {
 439→    from { transform: translateY(40px); opacity: 0; }
 440→    to   { transform: translateY(0);    opacity: 1; }
 441→  }
 442→
 443→  /* ── Header ── */
 444→  .scr-modal-header {
 445→    display: flex;
 446→    align-items: center;
 447→    justify-content: space-between;
 448→    padding: 1rem 1.25rem .75rem;
 449→    border-bottom: 1px solid var(--scr-border, #e5e7eb);
 450→    flex-shrink: 0;
 451→  }
 452→  .scr-modal-title {
 453→    font-size: 1.15rem;
 454→    font-weight: 700;
 455→    margin: 0;
 456→    color: var(--scr-text, #111);
 457→  }
 458→  .scr-modal-close {
 459→    display: flex;
 460→    align-items: center;
 461→    justify-content: center;
 462→    width: 36px;
 463→    height: 36px;
 464→    min-height: 44px;
 465→    min-width: 44px;
 466→    background: none;
 467→    border: none;
 468→    cursor: pointer;
 469→    border-radius: 50%;
 470→    color: var(--scr-muted, #6b7280);
 471→    padding: 0;
 472→    transition: background var(--scr-anim), color var(--scr-anim);
 473→  }
 474→  .scr-modal-close:hover { background: var(--scr-border, #e5e7eb); color: var(--scr-text, #111); }
 475→  .scr-modal-close:focus-visible {
 476→    outline: 3px solid var(--scr-primary);
 477→    outline-offset: 2px;
 478→  }
 479→
 480→  /* ── Tabs ── */
 481→  .scr-tabs {
 482→    display: flex;
 483→    border-bottom: 1px solid var(--scr-border, #e5e7eb);
 484→    flex-shrink: 0;
 485→    overflow-x: auto;
 486→    scrollbar-width: none;
 487→  }
 488→  .scr-tabs::-webkit-scrollbar { display: none; }
 489→
 490→  .scr-tab {
 491→    flex: 1;
 492→    padding: .7em 1em;
 493→    font-size: .9rem;
 494→    font-weight: 500;
 495→    background: none;
 496→    border: none;
 497→    border-bottom: 2px solid transparent;
 498→    cursor: pointer;
 499→    color: var(--scr-muted, #6b7280);
 500→    transition: color var(--scr-anim), border-color var(--scr-anim);
 501→    min-height: 44px;
 502→    white-space: nowrap;
 503→  }
 504→  .scr-tab--active {
 505→    color: var(--scr-primary);
 506→    border-bottom-color: var(--scr-primary);
 507→    font-weight: 600;
 508→  }
 509→  .scr-tab:focus-visible {
 510→    outline: 3px solid var(--scr-primary);
 511→    outline-offset: -3px;
 512→  }
 513→
 514→  /* ── Panels ── */
 515→  .scr-panel {
 516→    flex: 1;
 517→    overflow-y: auto;
 518→    padding: 1rem 1.25rem;
 519→    -webkit-overflow-scrolling: touch;
 520→  }
 521→  .scr-panel[hidden] { display: none; }
 522→  .scr-panel--active { display: block; }
 523→
 524→  /* ── Unit toggle ── */
 525→  .scr-unit-toggle {
 526→    display: flex;
 527→    align-items: center;
 528→    gap: .6rem;
 529→    margin-bottom: .75rem;
 530→    flex-wrap: wrap;
 531→  }
 532→  .scr-unit-label { font-size: .85rem; color: var(--scr-muted, #6b7280); }
 533→  .scr-unit-btn-group {
 534→    display: flex;
 535→    border: 1px solid var(--scr-border, #e5e7eb);
 536→    border-radius: 6px;
 537→    overflow: hidden;
 538→  }
